const slugify = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
const quote = s => JSON.stringify(s)
const content = a => {
  const slug = a.id
  const blocks = [{intro:a.lead}, ...a.sections.flatMap(([h,p])=>[{h2:h,id:slugify(h),toc:h},{p}]), ...(appBridges[a.id] ? [{bridge:appBridges[a.id]}] : []), {summary:a.summary}, {h2:'Em síntese',id:'conclusao',toc:'Conclusão'}, {p:a.end}, {note:'Conteúdo informativo. Não substitui avaliação individual nem orientação clínica ou educativa.'}]
  const faq = [
    ['Este tema aplica-se da mesma forma a todas as crianças?', 'Não. A decisão deve considerar desenvolvimento, preferências, contexto e avaliação individual.'],
    ['Quando devo pedir ajuda?', 'Quando a dificuldade persiste, afeta a comunicação, aprendizagem, segurança ou bem-estar, converse com profissionais qualificados e com a escola, conforme o contexto.'],
  ]
  return {id:a.id,slug,short:a.title,date:'2026-10-18',titleTag:`${a.title} · Fala+`,description:a.teaser,keywords:[a.title.toLowerCase(),...a.teaser.toLowerCase().split(/[ ,.;:!?]+/).filter(x=>x.length>5).slice(0,6)],h1:`<span class="word-highlight">${a.title}</span>`,lead:a.lead,blocks,faq,sources:a.sources,related:a.related}
}

for (const a of articles) {
  const dir=join(root,'_fonte','artigos','conteudo','pt'); mkdirSync(dir,{recursive:true})
  writeFileSync(join(dir,`${a.id}.mjs`),`export default ${JSON.stringify(content(a),null,2)}\n`,'utf8')
}
const catalog=articles.map(a=>({id:a.id,theme:a.id.startsWith('mito-')?'mitos':a.id.startsWith('brincadeira-')?'brincar':a.id.startsWith('gamificacao-')?'jogos':(['sono-desenvolvimento-linguagem','pac-vs-dificuldades-audicao','autismo-meninas-sinais-reconhecimento','comunicacao-multimodal-gestos-sinais','comportamento-dificil-quebra-comunicacao','modelagem-caa-app-crianca','intervencoes-naturalistas-autismo-evidencia'].includes(a.id)?'fala':'escola'),kind:{pt:a.id.startsWith('mito-')?'Mito ou Verdade':'Guia prático',en:'Guide',es:'Guía'},pt:{live:true,slug:a.id,title:a.title,teaser:a.teaser},en:null,es:null}))
writeFileSync(join(root,'_fonte','artigos','catalogo-novos.mjs'),`export default ${JSON.stringify(catalog,null,2)}\n`,'utf8')
